/*
 * prog46_postfix_stack – evaluate a postfix expression supplied on the command line.
 *
 * The original binary was heavily obfuscated.  By analysing the state‑machine
 * in the decompiled `main` the following clear‑cut behaviour was recovered:
 *
 *   • The program expects at least one argument (the postfix expression tokens).
 *   • Tokens are taken from argv[1] … argv[argc‑1]; at most 64 tokens are processed.
 *   • Each token is either
 *        – a signed decimal integer (the whole token must be a number), or
 *        – a single‑character operator: '+', '-', '*', '/'.
 *   • Numbers are pushed onto a stack (maximum depth 64).  Operators pop the two
 *     topmost values, apply the operation and push the result.
 *   • Any of the following conditions cause the program to print "ERROR"
 *     and exit with status 1:
 *        – insufficient operands for an operator,
 *        – division by zero,
 *        – stack overflow,
 *        – an invalid token,
 *        – more than 64 tokens,
 *        – after processing all tokens the stack does not contain exactly one value.
 *   • On success the single value left on the stack is printed as a signed
 *     decimal integer followed by a newline.
 *
 * The implementation below follows the same observable behaviour but is written
 * in clean C without the original obfuscation.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAX_TOKENS 64   /* maximum number of tokens the program will handle */
#define MAX_STACK  64   /* maximum depth of the evaluation stack */

int main(int argc, char *argv[])
{
    long stack[MAX_STACK];
    int top = 0;                 /* number of elements currently on the stack */
    int token_idx = 0;           /* index of the current token (0‑based) */
    int token_count;            /* how many tokens we will actually process */

    /* The original program required at least one token. */
    if (argc < 2) {
        puts("ERROR");
        return 1;
    }

    /* The original binary caps the number of tokens to 64 (0x40). */
    token_count = argc - 1;
    if (token_count > MAX_TOKENS)
        token_count = MAX_TOKENS;

    while (token_idx < token_count) {
        char *tok = argv[1 + token_idx];
        size_t len = strlen(tok);

        /* -------------------------------------------------
         *  Operator handling (single‑character tokens)
         * ------------------------------------------------- */
        if (len == 1 && (*tok == '+' || *tok == '-' || *tok == '*' || *tok == '/')) {
            /* Need two operands on the stack */
            if (top < 2) {
                puts("ERROR");
                return 1;
            }

            long b = stack[--top];   /* right operand */
            long a = stack[--top];   /* left  operand */
            long result = 0;

            switch (*tok) {
                case '+': result = a + b; break;
                case '-': result = a - b; break;
                case '*': result = a * b; break;
                case '/':
                    if (b == 0) {
                        puts("ERROR");
                        return 1;
                    }
                    result = a / b;
                    break;
            }

            /* Push the result, checking for overflow */
            if (top >= MAX_STACK) {
                puts("ERROR");
                return 1;
            }
            stack[top++] = result;
        }
        /* -------------------------------------------------
         *  Number handling (any other token)
         * ------------------------------------------------- */
        else {
            char *endptr;
            long val;

            errno = 0;
            val = strtol(tok, &endptr, 10);

            /* strtol must consume the whole token and must not overflow */
            if (errno != 0 || *endptr != '\0') {
                puts("ERROR");
                return 1;
            }

            if (top >= MAX_STACK) {
                puts("ERROR");
                return 1;
            }
            stack[top++] = val;
        }

        token_idx++;
    }

    /* After processing all tokens the stack must contain exactly one value */
    if (top != 1) {
        puts("ERROR");
        return 1;
    }

    printf("%ld\n", stack[0]);
    return 0;
}
